// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        vm.assume(seed < type(uint256).max / 15); // avoid overflow in block number manipulation
        uint256 blockNumber = seed * 15; // block number is multiple of 15
        vm.roll(blockNumber);
        uint256 initialBalance = address(c).balance;
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");
        if (success) {
            uint256 finalBalance = address(c).balance;
            assertTrue(finalBalance == initialBalance - 10 ether);
        }
    }
}

